import itertools

def solve_hamiltonian(instance):
    n = instance['n']
    edges = set()
    for u,v in instance['edges']:
        edges.add((u,v) if u<v else (v,u))
    if n <=2:
        return False
    verts = list(range(n))
    for perm in itertools.permutations(verts[1:]):
        cycle = (verts[0],) + perm
        ok=True
        for i in range(n):
            a=cycle[i]; b=cycle[(i+1)%n]
            if (a,b) if a<b else (b,a) not in edges:
                ok=False; break
        if ok:
            return True
    return False

inst={'n':3,'edges':[[0,1],[0,2],[1,2]]}
print(solve_hamiltonian(inst))
